def is_power_of_5(N):
    """Checks if N is a power of 5 and returns the exponent k if it is."""
    if N <= 0:
        return False, None
    k = 0
    temp_N = N
    while temp_N > 1:
        if temp_N % 5 != 0:
            return False, None
        temp_N //= 5
        k += 1
    return True, k

solutions = []
# Test n from 3 up to 20 as requested
for n in range(3, 21):
    X = (2**n) - 3
    is_power, k = is_power_of_5(X)
    if is_power:
        solutions.append((n, k))

print("Found solutions (n, k):")
for n, k in solutions:
    print(f"n={n}, k={k}, 2^{n}-3 = {5**k}")

def is_power_of_5(N):
    if N <= 0:
        return False
    while N > 1 and N % 5 == 0:
        N //= 5
    return N == 1

solutions = []
# Test n = 4m + 3 for m = 0 to 9 (n=3 up to n=39)
for m in range(10):
    n = 4 * m + 3
    N = (2**n) - 3

    if is_power_of_5(N):
        # Find k such that 5^k = N
        k = 0
        temp_N = N
        while temp_N > 1:
            temp_N //= 5
            k += 1
        solutions.append((n, k, N))

print("Solutions found in range n=3 to n=39 (n=4m+3):")
for sol in solutions:
    print(f"n={sol[0]}, k={sol[1]}, 2^n - 3 = {sol[2]} (which is 5^{sol[1]})")

if not solutions:
    print("No new solutions found in the specified range.")
else:
    print("\nAll solutions found:")
    for sol in solutions:
        print(sol)
